private val entries = ConcurrentHashMap<String, Entry>()
private val mutex = Mutex()

suspend fun read(id: String): Entity {
    entries[id]?.takeIf { !it.isExpired }?.let { return it.value }
    return mutex.withLock {                              // one loader at a time
        entries[id]?.takeIf { !it.isExpired }?.let { return it.value }
        val value = store.find(id)                       // source of truth on a miss
        entries[id] = Entry(value, deadline())
        value
    }
}
